import { test, expect } from '@playwright/test';

test.describe('Page Title Update on Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should update the title when navigating to the About section', async ({ page }) => {
    await page.getByRole('link', { name: 'About' }).click();
    await expect(page).toHaveTitle('About Us - Example'); // Replace with the expected title
  });

  test('should update the title when navigating to the Contact section', async ({ page }) => {
    await page.getByRole('link', { name: 'Contact' }).click();
    await expect(page).toHaveTitle('Contact Us - Example'); // Replace with the expected title
  });
});
